const express = require('express');
const NodeCache = require('node-cache');

const app = express();
const quoteCache = new NodeCache({ stdTTL: 1800, checkperiod: 120 });

// Endpoint to retrieve cached freight rate quotation
app.get('/api/logistics/quotes/:quoteId', (req, res) => {
  const { quoteId } = req.params;

  // Key cache by tenant or verify tenant ownership against authenticated user
  const cachedQuote = quoteCache.get(`quote_${quoteId}`);
  if (!cachedQuote || cachedQuote.tenantId !== req.user.tenantId) {
    return res.status(404).json({ error: 'Quote expired or not found' });
  }

  return res.json({
    quoteId: cachedQuote.id,
    origin: cachedQuote.origin,
    destination: cachedQuote.destination,
    discountedRate: cachedQuote.discountedRate,
    shipperDetails: cachedQuote.shipper
  });
});

module.exports = app;
